  function refreshPaymentRouteCreateUi(slot){
    if(isCheckoutPaymentShellSlot(slot) && data.checkoutSummary.visible && els.checkoutSummary && els.checkoutSummary.dataset.renderingPaymentShell !== '1'){
      const activePaid = hasPaidActiveSubscription(data.currentModel || {});
      const summary = validCheckoutSummary(activePaid);
      if(summary){
        renderPlanCheckoutSummary(summary.plan, summary.flowType, { loadPreview: false });
        return;
      }
    }
    const actionContainer = pane.querySelector(`[data-subp-payment-route-create-action="${slot}"]`);
    if(actionContainer){
      const inPaymentShell = !!actionContainer.closest('[data-subp-payment-shell][data-step="payment"]');
      actionContainer.innerHTML = isCheckoutPaymentShellSlot(slot)
        ? inPaymentShell
          ? securePaymentRouteCreateActionHtml(slot)
          : checkoutSummaryOpenSecurePaymentActionHtml(slot)
        : paymentRouteCreateActionHtml(slot);
    }
    const statusContainer = pane.querySelector(`[data-subp-payment-route-create-status="${slot}"]`);
    if(statusContainer){
      statusContainer.innerHTML = paymentRouteCreateStatusHtml(slot);
    }
  }

  function generatePaymentServerPreviewKey(payload){
    const routeType = clean(payload?.route_type) || 'route';
    const entityType = clean(payload?.entity_type).toLowerCase() || 'entity';
    const entityId = safeDoctorId(payload?.entity_id) || 'unknown';
    const target = clean(payload?.target_plan_code) || clean(payload?.current_plan_code) || 'current';
    return `mxmed-preview:${routeType}:${entityType}:${entityId}:${target}:${Date.now()}`;
  }

  function paymentServerPreviewElement(slot){
    return pane.querySelector(`[data-subp-server-preview="${slot}"]`);
  }

  function paymentServerPreviewRouteLabel(routeType){
    const route = clean(routeType);
    if(route === 'upgrade_subscription') return 'Mejora de plan';
    if(route === 'renewal') return 'Renovación';
    if(route === 'new_subscription') return 'Contratación';
    return route || 'Ruta de pago';
  }

  function paymentServerPreviewNextActionLabel(nextAction){
    const type = clean(nextAction?.type);
    const enabled = nextAction?.enabled === true;
    const action = type === 'stripe_checkout_sandbox_pending'
      ? 'Stripe sandbox pendiente'
      : (type || 'Pendiente');
    return `${action} · enabled=${enabled ? 'true' : 'false'}`;
  }

  function paymentServerPreviewHtml(slot){
    const isSimulation = isQaPlanSimulationActive();
    const chip = isSimulation ? 'QA local' : 'Cálculo seguro';
    const body = isSimulation
      ? `<p class="subp-server-preview-note">Simulación QA local — sin consulta backend.</p>
         <p class="subp-server-preview-muted">El cálculo backend sólo se consulta en modo Real.</p>`
      : `<p class="subp-server-preview-note">Estamos confirmando el importe seguro antes de habilitar el pago.</p>`;
    return `<article class="subp-server-preview" data-subp-server-preview="${escapeHtml(slot)}" data-state="${isSimulation ? 'simulation' : 'idle'}">
        <div class="subp-server-preview-head">
          <div>
            <div class="subp-payments-kicker">Importe seguro</div>
            <h4>Validación del pago</h4>
          </div>
          <span class="subp-payments-status-chip">${escapeHtml(chip)}</span>
        </div>
        <div class="subp-server-preview-body" data-subp-server-preview-body>${body}</div>
      </article>`;
  }

  function renderPaymentServerPreviewState(slot, state){
    const container = paymentServerPreviewElement(slot);
    if(!container) return;
    const body = container.querySelector('[data-subp-server-preview-body]');
    if(!body) return;
    const status = clean(state?.state) || 'idle';
    container.dataset.state = status;

    if(status === 'simulation'){
      body.innerHTML = `<p class="subp-server-preview-note">Simulación QA local — sin consulta backend.</p>
        <p class="subp-server-preview-muted">El cálculo backend sólo se consulta en modo Real.</p>`;
      refreshPaymentRouteCreateUi(slot);
      return;
    }

    if(status === 'loading'){
      body.innerHTML = '<p class="subp-server-preview-note">Calculando importe seguro...</p>';
      refreshPaymentRouteCreateUi(slot);
      return;
    }

    if(status === 'success'){
      const preview = state?.data || {};
      const amount = formatSubscriptionCents(preview.amount_cents, preview.currency) || 'Se confirmará antes del pago';
      const warnings = Array.isArray(preview.warnings) ? preview.warnings.map(clean).filter(Boolean) : [];
      const reasons = Array.isArray(preview.reasons) ? preview.reasons.map(clean).filter(Boolean) : [];
      const notices = [...warnings, ...reasons];
      body.innerHTML = `<p class="subp-server-preview-note">Importe confirmado para continuar: <strong>${escapeHtml(amount)}</strong>.</p>
        ${notices.length && isSubscriptionDebugPanelEnabled() ? `<p class="subp-server-preview-muted">Avisos QA: ${escapeHtml(notices.join(', '))}</p>` : ''}
        ${paymentShellDebugDetailsHtml('Detalles técnicos QA', [
          { label: 'Ruta', value: paymentServerPreviewRouteLabel(preview.route_type) },
          { label: 'Importe server-side', value: amount },
          { label: 'Moneda', value: clean(preview.currency) || 'MXN' },
          { label: 'Fuente', value: clean(preview.amount_source) || 'server_recalculated' },
          { label: 'Diferencia con frontend', value: preview.amount_mismatch === true ? 'Sí' : 'No' },
          { label: 'Siguiente acción', value: paymentServerPreviewNextActionLabel(preview.next_action) }
        ], preview)}`;
      refreshCheckoutSummaryAmount(slot);
      refreshPaymentRouteCreateUi(slot);
      return;
    }

    if(status === 'error'){
      const code = clean(state?.errorCode);
      const message = clean(state?.message) || 'No fue posible calcular la vista previa server-side. El monto final se confirmará antes del pago.';
      body.innerHTML = `<p class="subp-server-preview-note">${escapeHtml(message)}</p>
        ${code && isSubscriptionDebugPanelEnabled() ? `<p class="subp-server-preview-muted">Respuesta controlada: ${escapeHtml(code)}.</p>` : ''}`;
      refreshPaymentRouteCreateUi(slot);
      return;
    }

    body.innerHTML = '<p class="subp-server-preview-note">Estamos confirmando el importe seguro antes de habilitar el pago.</p>';
    refreshPaymentRouteCreateUi(slot);
  }

  async function loadPaymentServerPreview(slot, payload){
    if(!payload){
      renderPaymentServerPreviewState(slot, {
        state: 'error',
        errorCode: 'missing_payload',
        message: 'No fue posible preparar la vista previa server-side.'
      });
      return false;
    }

    if(isQaPlanSimulationActive()){
      renderPaymentServerPreviewState(slot, { state: 'simulation' });
      return true;
    }

    const endpoint = buildPaymentRoutePreviewEndpoint(payload.entity_type, payload.entity_id);
    if(!endpoint){
      renderPaymentServerPreviewState(slot, {
        state: 'error',
        errorCode: 'missing_entity_context',
        message: 'No fue posible resolver la entidad para calcular la vista previa server-side.'
      });
      return false;
    }

    const requestId = Date.now() + Math.random();
    if(!data.paymentServerPreview) data.paymentServerPreview = {};
    data.paymentServerPreview[slot] = { state: 'loading', requestId };
    renderPaymentServerPreviewState(slot, { state: 'loading' });

    try{
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Idempotency-Key': generatePaymentServerPreviewKey(payload)
        },
        credentials: 'same-origin',
        body: JSON.stringify(buildPaymentServerPreviewPayload(payload))
      });
      const responsePayload = await response.json().catch(()=> null);
      if(data.paymentServerPreview?.[slot]?.requestId !== requestId) return false;
      if(!response.ok || !responsePayload || responsePayload.ok !== true || !responsePayload.data){
        const errorCode = clean(responsePayload?.error?.code) || `http_${response.status || 0}`;
        const errorMessage = clean(responsePayload?.error?.message) || 'No fue posible calcular la vista previa server-side. El monto final se confirmará antes del pago.';
        data.paymentServerPreview[slot] = {
          state: 'error',
          requestId,
          httpStatus: Number(response.status || 0),
          errorCode,
          message: errorMessage
        };
        renderPaymentServerPreviewState(slot, data.paymentServerPreview[slot]);
        return false;
      }

      data.paymentServerPreview[slot] = {
        state: 'success',
        requestId,
        httpStatus: Number(response.status || 0),
        data: responsePayload.data
      };
      renderPaymentServerPreviewState(slot, data.paymentServerPreview[slot]);
      return true;
    }catch(_){
      if(data.paymentServerPreview?.[slot]?.requestId !== requestId) return false;
      data.paymentServerPreview[slot] = {
        state: 'error',
        requestId,
        httpStatus: 0,
        errorCode: 'network_error',
        message: 'No fue posible calcular la vista previa server-side. El monto final se confirmará antes del pago.'
      };
      renderPaymentServerPreviewState(slot, data.paymentServerPreview[slot]);
      return false;
    }
  }

  async function createPaymentRouteFromSummary(slot){
    const key = slot === 'renewal' ? 'renewal' : 'checkoutSummary';
    const payload = data.paymentPayloadPreview?.[key];
    const state = paymentRouteCreateState(key);

    if(isQaPlanSimulationActive()){
      state.state = 'error';
      state.httpStatus = 0;
      state.errorCode = 'qa_simulation';
      state.message = 'Disponible sólo en modo Real.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(key === 'checkoutSummary' && !paymentExecutionStateMatchesCurrentSummary(key)){
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(!payload){
      state.state = 'error';
      state.httpStatus = 0;
      state.errorCode = 'missing_payload';
      state.message = 'No fue posible preparar los datos para el pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    const preview = latestPaymentServerPreviewData(key);
    if(!preview){
      state.state = 'error';
      state.httpStatus = 0;
      state.errorCode = 'preview_required';
      state.message = 'Primero confirma el importe con backend.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(paymentExecutionBlockReason(key) === 'stripe_billing_not_ready'){
      state.state = 'error';
      state.httpStatus = 409;
      state.errorCode = 'monthly_recurring_not_ready';
      state.message = 'Pago mensual automático en preparación.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(key === 'checkoutSummary' && !paymentExecutionStateMatchesCurrentSummary(key)){
      refreshPaymentRouteCreateUi(key);
      return false;
    }
    if(key === 'checkoutSummary'){
      setCheckoutSummarySecurePaymentVisible(true);
    }

    const endpoint = buildPaymentRouteCreateEndpoint(payload.entity_type, payload.entity_id);
    if(!endpoint){
      state.state = 'error';
      state.httpStatus = 0;
      state.errorCode = 'missing_entity_context';
      state.message = 'No fue posible resolver la entidad para preparar el pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    const signature = paymentRouteCreateSignature(payload);
    if(state.signature !== signature){
      resetPaymentRouteCreate(key);
      paymentRouteCreateState(key).signature = signature;
    }
    const currentState = paymentRouteCreateState(key);
    if(!currentState.idempotencyKey){
      currentState.idempotencyKey = generatePaymentRouteCreateKey(payload);
    }
    currentState.state = 'creating';
    currentState.httpStatus = 0;
    currentState.data = null;
    currentState.errorCode = '';
    currentState.message = '';
    refreshPaymentRouteCreateUi(key);

    try{
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Idempotency-Key': currentState.idempotencyKey
        },
        credentials: 'same-origin',
        body: JSON.stringify(buildPaymentRouteCreatePayload(payload, preview))
      });
      const responsePayload = await response.json().catch(()=> null);
      const responseData = responsePayload?.data || null;
      if(response.ok && responsePayload?.ok === true && responseData){
        currentState.state = 'success';
        currentState.httpStatus = Number(response.status || 0);
        currentState.data = responseData;
        currentState.checkoutBridge = paymentRouteCheckoutBridgeInitialState();
        currentState.errorCode = '';
        currentState.message = '';
        persistPreparedPaymentRouteState(key);
        refreshPaymentRouteCreateUi(key);
        return true;
      }

      const errorCode = clean(responsePayload?.error?.code) || `http_${response.status || 0}`;
      const errorMessage = clean(responsePayload?.error?.message) || clean(responsePayload?.message);
      currentState.state = 'error';
      currentState.httpStatus = Number(response.status || 0);
      currentState.data = null;
      currentState.errorCode = errorCode;
      currentState.message = paymentRouteCreateErrorMessage(errorCode, response.status, errorMessage);
      refreshPaymentRouteCreateUi(key);
      return false;
    }catch(_){
      currentState.state = 'error';
      currentState.httpStatus = 0;
      currentState.data = null;
      currentState.errorCode = 'network_error';
      currentState.message = 'No fue posible preparar el pago seguro. Inténtalo más tarde.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }
  }

  async function createCheckoutFromPaymentRoute(slot){
    const key = slot === 'renewal' ? 'renewal' : 'checkoutSummary';
    const routeState = paymentRouteCreateState(key);
    const bridge = paymentRouteCheckoutBridgeState(key);
    const route = routeState.data && typeof routeState.data === 'object' ? routeState.data : null;
    const routeUuid = clean(route?.payment_route_uuid);

    if(isQaPlanSimulationActive()){
      bridge.state = 'error';
      bridge.httpStatus = 0;
      bridge.errorCode = 'qa_simulation';
      bridge.message = 'Disponible sólo en modo Real.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(key === 'checkoutSummary' && !paymentExecutionStateMatchesCurrentSummary(key)){
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(routeState.state !== 'success' || !route || !routeUuid){
      bridge.state = 'error';
      bridge.httpStatus = 0;
      bridge.errorCode = 'missing_payment_route';
      bridge.message = 'Primero prepara el pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    const endpoint = buildPaymentRouteCheckoutEndpoint(route.entity_type, route.entity_id, routeUuid);
    if(!endpoint){
      bridge.state = 'error';
      bridge.httpStatus = 0;
      bridge.errorCode = 'missing_entity_context';
      bridge.message = 'No fue posible resolver la preparación del pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(!bridge.idempotencyKey){
      bridge.idempotencyKey = `mxmed-ui-checkout-bridge-${routeUuid}`;
    }
    bridge.state = 'creating';
    bridge.httpStatus = 0;
    bridge.data = null;
    bridge.errorCode = '';
    bridge.message = '';
    persistPreparedPaymentRouteState(key);
    refreshPaymentRouteCreateUi(key);

    try{
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Idempotency-Key': bridge.idempotencyKey
        },
        credentials: 'same-origin',
        body: JSON.stringify({
          provider: 'none',
          notes: 'QA checkout bridge from UI prepared route; no payment intent'
        })
      });
      const responsePayload = await response.json().catch(()=> null);
      const responseData = responsePayload?.data || null;
      if(response.ok && responsePayload?.ok === true && responseData){
        bridge.state = 'success';
        bridge.httpStatus = Number(response.status || 0);
        bridge.data = responseData;
        bridge.paymentIntent = paymentIntentCreateInitialState();
        bridge.errorCode = '';
        bridge.message = '';
        routeState.data = {
          ...routeState.data,
          status: clean(responseData.status) || clean(routeState.data.status),
          checkout_intent_uuid: clean(responseData.checkout_intent_uuid) || routeState.data.checkout_intent_uuid,
          checkout_created_at: clean(responseData.checkout_created_at) || routeState.data.checkout_created_at,
          provider_status: clean(responseData.provider_status) || routeState.data.provider_status,
          next_action: responseData.next_action || routeState.data.next_action
        };
        persistPreparedPaymentRouteState(key);
        refreshPaymentRouteCreateUi(key);
        return true;
      }

      const errorCode = clean(responsePayload?.error?.code) || `http_${response.status || 0}`;
      const errorMessage = clean(responsePayload?.error?.message) || clean(responsePayload?.message);
      bridge.state = 'error';
      bridge.httpStatus = Number(response.status || 0);
      bridge.data = null;
      bridge.errorCode = errorCode;
      bridge.message = paymentRouteCheckoutBridgeErrorMessage(errorCode, response.status, errorMessage);
      persistPreparedPaymentRouteState(key);
      refreshPaymentRouteCreateUi(key);
      return false;
    }catch(_){
      bridge.state = 'error';
      bridge.httpStatus = 0;
      bridge.data = null;
      bridge.errorCode = 'network_error';
      bridge.message = 'No fue posible preparar el pago seguro. Inténtalo más tarde.';
      persistPreparedPaymentRouteState(key);
      refreshPaymentRouteCreateUi(key);
      return false;
    }
  }

  async function createPaymentIntentFromCheckout(slot){
    const key = slot === 'renewal' ? 'renewal' : 'checkoutSummary';
    const routeState = paymentRouteCreateState(key);
    const bridge = paymentRouteCheckoutBridgeState(key);
    const paymentIntent = paymentIntentCreateState(key);
    const route = routeState.data && typeof routeState.data === 'object' ? routeState.data : null;
    const checkout = bridge.data && typeof bridge.data === 'object' ? bridge.data : null;
    const checkoutUuid = clean(checkout?.checkout_intent_uuid);

    if(isQaPlanSimulationActive()){
      paymentIntent.state = 'error';
      paymentIntent.httpStatus = 0;
      paymentIntent.errorCode = 'qa_simulation';
      paymentIntent.message = 'Disponible sólo en modo Real.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(key === 'checkoutSummary' && !paymentExecutionStateMatchesCurrentSummary(key)){
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(routeState.state !== 'success' || !route){
      paymentIntent.state = 'error';
      paymentIntent.httpStatus = 0;
      paymentIntent.errorCode = 'missing_payment_route';
      paymentIntent.message = 'Primero prepara el pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(bridge.state !== 'success' || !checkoutUuid){
      paymentIntent.state = 'error';
      paymentIntent.httpStatus = 0;
      paymentIntent.errorCode = 'missing_checkout_intent';
      paymentIntent.message = 'Primero prepara el pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    const endpoint = buildPaymentIntentCreateEndpoint(route.entity_type, route.entity_id, checkoutUuid);
    if(!endpoint){
      paymentIntent.state = 'error';
      paymentIntent.httpStatus = 0;
      paymentIntent.errorCode = 'missing_entity_context';
      paymentIntent.message = 'No fue posible resolver el checkout para crear el pago seguro.';
      refreshPaymentRouteCreateUi(key);
      return false;
    }

    if(!paymentIntent.idempotencyKey){
      paymentIntent.idempotencyKey = `mxmed-ui-payment-intent-${checkoutUuid}`;
    }
    destroySubscriptionStripePaymentElement('payment_intent_create');
    paymentIntent.state = 'creating';
    paymentIntent.httpStatus = 0;
    paymentIntent.data = null;
    paymentIntent.errorCode = '';
    paymentIntent.message = '';
    persistPreparedPaymentRouteState(key);
    refreshPaymentRouteCreateUi(key);

    try{
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Idempotency-Key': paymentIntent.idempotencyKey
        },
        credentials: 'same-origin',
        body: JSON.stringify({
          provider: 'stripe',
          source: 'payment_intent',
          notes: 'QA Stripe sandbox PaymentIntent from prepared checkout; no payment confirmation in this microphase',
          metadata: {
            qa: 'stripe_sandbox_ui_e2e',
            flow: 'checkout_to_payment_intent',
            activation: 'forbidden_in_this_microphase'
          }
        })
      });
      const responsePayload = await response.json().catch(()=> null);
      const responseData = sanitizePaymentIntentResponse(responsePayload?.data || null);
      if(response.ok && responsePayload?.ok === true && responseData){
        paymentIntent.state = 'success';
        paymentIntent.httpStatus = Number(response.status || 0);
        paymentIntent.data = responseData;
        paymentIntent.errorCode = '';
        paymentIntent.message = '';
        persistPreparedPaymentRouteState(key);
        refreshPaymentRouteCreateUi(key);
        requestSubscriptionStripePaymentElementMountAfterCreate(
          key,
          responseData,
          response.status
        );
        return true;
      }

      const errorCode = clean(responsePayload?.error?.code) || `http_${response.status || 0}`;
      const errorMessage = clean(responsePayload?.error?.message) || clean(responsePayload?.message);
      paymentIntent.state = 'error';
      paymentIntent.httpStatus = Number(response.status || 0);
      paymentIntent.data = null;
      paymentIntent.errorCode = errorCode;
      paymentIntent.message = paymentIntentCreateErrorMessage(errorCode, response.status, errorMessage);
      persistPreparedPaymentRouteState(key);
      refreshPaymentRouteCreateUi(key);
      return false;
    }catch(_){
      paymentIntent.state = 'error';
      paymentIntent.httpStatus = 0;
      paymentIntent.data = null;
      paymentIntent.errorCode = 'network_error';
      paymentIntent.message = 'No fue posible crear el pago seguro. Inténtalo más tarde.';
      persistPreparedPaymentRouteState(key);
      refreshPaymentRouteCreateUi(key);
      return false;
    }
  }

  function paymentPayloadPreviewHtml(payload){
    if(!payload || !isSubscriptionDebugPanelEnabled()) return '';
    const json = JSON.stringify(payload, null, 2);
    return `<details class="subp-payment-payload-preview" data-subp-payment-payload-preview>
        <summary>QA payload conceptual read-only</summary>
        <pre>${escapeHtml(json)}</pre>
        <p>Vista frontend informativa. Backend debe recalcular importes, vigencias e idempotencia antes de crear cualquier pago.</p>
      </details>`;
  }

  function renderPricingModeToggle(){
    els.pricingModeButtons.forEach((button)=>{
      const active = clean(button.dataset.subpPricingMode) === pricingMode();
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
  }

  function readHeaderPlanName(){
    const raw = clean(document.querySelector('.mx-gh-current-plan-name')?.textContent);
    return raw.replace(/^Plan\s+/i, '').trim();
  }

  function headerPlanLabelFromModel(model, planLabel){
    const directLabel = clean(planLabel) || clean(model?.plan_label);
    if(directLabel && directLabel.toLowerCase() !== 'no disponible') return directLabel;
    const code = clean(model?.effective_plan_code)
      || clean(model?.contracted_plan_code)
      || clean(model?.plan_code);
    const plan = findPlanById(code);
    return clean(plan?.name) || code;
  }

  function headerRenewalLabelFromModel(model){
    const billingPeriod = clean(model?.billing_period).toLowerCase();
    if(billingPeriod === 'lifetime' || Number(model?.duration_days) === 0){
      return 'Vigencia permanente';
    }

    const expiresAt = clean(model?.expires_at);
    if(!expiresAt) return '';
    const match = expiresAt.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if(!match) return `Vigencia ${expiresAt}`;

    const [, year, month, day] = match;
    const date = new Date(Number(year), Number(month) - 1, Number(day));
    if(Number.isNaN(date.getTime())) return `Vigencia ${expiresAt}`;

    return `Vigencia ${date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: 'short',
      year: 'numeric'
    })}`;
  }

  function syncGlobalSubscriptionHeader(model, planLabel){
    const planNameEl = document.querySelector('.mx-gh-current-plan-name');
    const renewalEl = document.querySelector('.mx-gh-current-plan-renewal');
    const container = document.querySelector('.mx-gh-current-plan');
    const trigger = document.querySelector('.mx-gh-current-plan-trigger');
    const labelEl = document.querySelector('.mx-gh-current-plan-label');
    const isFreeQa = model?.qa_plan_simulated === true && clean(model?.qa_plan_mode) === 'free';
    const hasCurrentPaidPlan = hasPaidActiveSubscription(model || {});
    const resolvedPlanLabel = headerPlanLabelFromModel(model, planLabel);
    const renewalLabel = headerRenewalLabelFromModel(model);
    const resolvedPlanCode = clean(model?.effective_plan_code)
      || clean(model?.contracted_plan_code)
      || clean(model?.plan_code)
      || resolvedPlanLabel;
    const currentPlanIdentity = (isFreeQa || !hasCurrentPaidPlan)
      ? 'free'
      : normalizePlanId(resolvedPlanCode);

    if(labelEl){
      labelEl.textContent = currentPlanIdentity === 'free' ? 'Plan' : 'Tu plan actual';
    }

    if(planNameEl && resolvedPlanLabel){
      planNameEl.textContent = clean(resolvedPlanLabel.replace(/^Plan\s+/i, ''));
      planNameEl.dataset.subscriptionPlanCode = clean(model?.effective_plan_code)
        || clean(model?.contracted_plan_code)
        || clean(model?.plan_code);
      planNameEl.dataset.subscriptionPlanLabel = resolvedPlanLabel;
      planNameEl.dataset.currentPlan = currentPlanIdentity;
    }

    if(renewalEl){
      renewalEl.textContent = renewalLabel;
      renewalEl.dataset.subscriptionExpiresAt = clean(model?.expires_at);
    }

    if(container){
      container.dataset.currentPlan = currentPlanIdentity;
      container.classList.toggle('is-free-plan', currentPlanIdentity === 'free');
    }

    if(container && (resolvedPlanLabel || renewalLabel)){
      const label = [resolvedPlanLabel ? `Plan actual ${resolvedPlanLabel}` : '', renewalLabel]
        .filter(Boolean)
        .join('. ');
      container.setAttribute('aria-label', label);
      if(trigger) trigger.setAttribute('aria-label', label ? `${label}. Mostrar detalle de vigencia.` : 'Mostrar detalle de vigencia del plan');
    }
  }

  function planFlowType(plan, activePaid){
    const currentRank = planRank(data.current.id);
    const cardRank = planRank(plan?.id);
    if(!activePaid) return 'new_subscription';
    if(currentRank === null || cardRank === null) return 'unknown_active';
    if(cardRank < currentRank) return 'downgrade_at_renewal';
    if(cardRank === currentRank) return 'current';
    return 'upgrade_now';
  }

  function planActionCtaLabel(plan, flowType){
    const planLabel = clean(plan?.name) || 'plan';
    if(flowType === 'new_subscription') return 'Elegir este plan';
    if(flowType === 'upgrade_now') return `Mejorar a ${planLabel}`;
    if(flowType === 'renewal') return `Renovar ${planLabel}`;
    return '';
  }

  function currentBillingPeriod(){
    return clean(data.currentModel?.billing_period).toLowerCase();
  }

  function currentPlanLabel(){
    return clean(data.currentModel?.plan_label)
      || clean(findPlanById(data.current.id)?.name)
      || clean(data.current.name)
      || 'Plan actual';
  }

  function currentBillingPeriodLabel(){
    const period = currentBillingPeriod();
    if(period === 'annual') return 'Pago anual';
    if(period === 'monthly') return 'Pago mensual';
    if(period === 'lifetime') return 'Vitalicio';
    return 'No disponible';
  }

  function setSubscriptionSection(section){
    const next = section === 'billing' ? 'billing' : 'plans';
    if(next !== data.activeSection){
      destroySubscriptionStripePaymentElement('subscription_section_changed');
    }
    data.activeSection = next;
    if(next === 'plans'){
      data.paymentsView = 'overview';
    }else{
      closePlanCheckoutSummary({ render: false });
    }
    closeBenefitInfoPopovers(els.catalog);
    els.sectionTabs.forEach((button)=>{
      const isActive = clean(button.dataset.subpSectionTab) === next;
      button.classList.toggle('is-active', isActive);
      button.setAttribute('aria-selected', isActive ? 'true' : 'false');
    });
    els.sectionPanels.forEach((panel)=>{
      const isActive = clean(panel.dataset.subpSection) === next;
      panel.classList.toggle('d-none', !isActive);
    });
    if(next === 'billing'){
      renderSubscriptionPaymentsShell();
    }else{
      renderCatalog();
    }
  }

  function subscriptionPaymentsBenefitsHtml(features){
    const items = Array.isArray(features)
      ? features.map(clean).filter((feature)=> feature && !feature.includes(':')).slice(0, 6)
      : [];
    if(!items.length){
      return '<p class="subp-payments-muted mb-0">Beneficios vigentes por consultar.</p>';
    }
    return `<ul class="subp-payments-benefits">
      ${items.map((feature)=>`<li><span class="material-symbols-rounded" aria-hidden="true">check_circle</span>${escapeHtml(feature)}</li>`).join('')}
    </ul>`;
  }

  function subscriptionPaymentsMethodsHtml(){
    return `<div class="subp-payments-methods">
      <div class="subp-payments-method">
        <span class="material-symbols-rounded" aria-hidden="true">credit_card</span>
        <div>
          <strong>Tarjeta</strong>
          <p>Pago seguro con tarjeta. Permitirá renovación automática cuando exista un método guardado.</p>
        </div>
        <em>Próxima fase</em>
      </div>
      <div class="subp-payments-method">
        <span class="material-symbols-rounded" aria-hidden="true">account_balance</span>
        <div>
          <strong>SPEI / transferencia bancaria</strong>
          <p>Pago manual por transferencia. La renovación se activará cuando el pago sea conciliado.</p>
        </div>
        <em>Próxima fase</em>
      </div>
    </div>`;
  }

  function subscriptionPaymentsDisabledButton(label){
    return `<button class="btn btn-outline-secondary btn-sm" type="button" disabled>${escapeHtml(label)}</button>`;
  }

  function renewalPriceLabel(plan){
    const billingPeriod = currentBillingPeriod();
    if(billingPeriod === 'annual'){
      const annual = planAnnualPrice(plan);
      return annual > 0 ? `${fmtMoney(annual)} al año` : 'Se confirmará antes del pago.';
    }
    if(billingPeriod === 'monthly'){
      const monthly = planMonthlyPaymentPrice(plan);
      return monthly > 0 ? `${fmtMoney(monthly)} / mes` : 'Se confirmará antes del pago.';
    }
    return 'Se confirmará antes del pago.';
  }

  function addDays(date, days){
    if(!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    const copy = new Date(date.getTime());
    copy.setDate(copy.getDate() + Number(days || 0));
    return Number.isNaN(copy.getTime()) ? null : copy;
  }

  function estimatedRenewalUntilLabel(){
    const expiresAt = parseSubscriptionDate(data.currentModel?.expires_at);
    const billingPeriod = currentBillingPeriod();
    const modelDuration = Number(data.currentModel?.duration_days || 0);
    const durationDays = modelDuration > 0
      ? modelDuration
      : (billingPeriod === 'annual' ? 365 : 0);
    const renewedUntil = durationDays > 0 ? addDays(expiresAt, durationDays) : null;
    return renewedUntil ? formatDate(formatQaDateForModel(renewedUntil)) : 'Se confirmará antes del pago.';
  }

  function remainingDaysLabel(){
    const modelDays = Number(data.currentModel?.days_until_expiration);
    if(Number.isFinite(modelDays) && modelDays >= 0){
      return `${Math.round(modelDays)} días restantes`;
    }
    const expiresAt = parseSubscriptionDate(data.currentModel?.expires_at);
    if(!expiresAt) return 'Se confirmará antes del pago.';
    const dayMs = 24 * 60 * 60 * 1000;
    return `${Math.max(0, Math.ceil((expiresAt.getTime() - Date.now()) / dayMs))} días restantes`;
  }

