  function normalizePreviewList(values){
    const out = [];
    const seen = new Set();
    (Array.isArray(values) ? values : []).forEach((value)=>{
      const item = clean(value);
      if(!item) return;
      const key = item.toLowerCase();
      if(seen.has(key)) return;
      seen.add(key);
      out.push(item);
    });
    return out;
  }
  function extractNamedList(values){
    if(!Array.isArray(values)) return [];
    const out = [];
    values.forEach((entry)=>{
      if(typeof entry === 'string'){
        out.push(clean(entry));
        return;
      }
      if(!entry || typeof entry !== 'object') return;
      out.push(clean(
        entry.label
        || entry.name
        || entry.title
        || entry.text
        || entry.study_name
        || entry.item_name
        || entry.preset_name
        || entry.profile_name
      ));
    });
    return normalizePreviewList(out);
  }
  function extractPresetNamesFromPayload(payload){
    if(!payload || typeof payload !== 'object') return [];
    const keys = [
      'requested_packages',
      'packages',
      'package_names',
      'requested_profiles',
      'profiles',
      'profile_names',
      'requested_presets',
      'presets',
      'preset_names',
      'requested_panels',
      'panels',
      'panel_names'
    ];
    const names = [];
    keys.forEach((key)=>{
      names.push(...extractNamedList(payload[key]));
    });
    return normalizePreviewList(names);
  }
